using System;
using System.IO;
using System.Linq;
using System.Text.Json;
using BibleSurvivor.Core;

namespace BibleSurvivor.Sim;

internal static class Program
{
    private static int Main(string[] args)
    {
        try
        {
            var weapon=args.Length>0?args[0]:"bible";
            var round=CatalogReader.Adam("content/genesis/catalog.json");
            var snapshot=GameSnapshot.New(); var game=new AdamSession(snapshot,round,weapon);
            var killed=0;var rawXp=0;
            // Deterministic rule demonstration: kills are injected, NOT generated by real combat/physics.
            for(var tick=0;tick<1800 && game.IsActive;tick++)
            {
                Resolve(game);game.Advance(.1);
                if(game.Wave==null) break;
                foreach(var enemy in game.Wave.Active.Values.ToArray())
                {
                    Resolve(game);rawXp+=enemy.RawExperience;game.Kill(enemy.Id);killed++;
                    game.Collect(enemy.Id);Resolve(game);
                }
            }
            Resolve(game);game.Capture();
            var folder=System.IO.Path.Combine(".local","simulation-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);
            var store=new SaveStore(System.IO.Path.Combine(folder,"save.json"));store.Commit(snapshot,0,"r01-simulation");
            var saved=store.Load()!;
            var passed=killed==240 && rawXp==300 && saved.Profile.Gold==73 && saved.Run?.RoundNumber==2;
            Console.WriteLine(JsonSerializer.Serialize(new {
                status=passed?"PASS":"FAIL",kind="injected-kill core simulation; not gameplay",starting_weapon=weapon,
                killed,raw_xp=rawXp,level=game.Growth.Level,gold=saved.Profile.Gold,next_round=saved.Run?.RoundNumber,
                save_roundtrip="PASS",unity="NOT_RUN",mobile="NOT_RUN" },new JsonSerializerOptions {WriteIndented=true}));
            return passed?0:1;
        }
        catch(Exception error) {Console.Error.WriteLine(error);return 1;}
    }
    private static void Resolve(AdamSession game)
    {
        while(game.PendingChoices.Count>0)
        {
            var id=game.PendingChoices.FirstOrDefault(x=>x!="scroll")??game.PendingChoices[0];
            if(!game.Choose(id)) throw new InvalidOperationException("Choice refused");
        }
    }
}
